<?php session_start(); require __DIR__.'/includes/db.php'; if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;} $uid=(int)$_SESSION['user_id'];$address=trim($_POST['shipping_address']??'');$payment=$_POST['payment_method']??'Cash on Delivery';$allowed=['Cash on Delivery','bKash','Nagad','Card Payment'];if($address===''||!in_array($payment,$allowed,true)){die('Invalid checkout information.');}$conn->begin_transaction();try{$st=mysqli_prepare($conn,"SELECT c.product_id,c.quantity,p.price,p.stock,p.name FROM cart c JOIN products p ON c.product_id=p.id WHERE c.user_id=? FOR UPDATE");mysqli_stmt_bind_param($st,'i',$uid);mysqli_stmt_execute($st);$res=mysqli_stmt_get_result($st);$items=[];$total=0;while($i=mysqli_fetch_assoc($res)){if($i['quantity']>$i['stock'])throw new Exception('Insufficient stock for '.$i['name']);$items[]=$i;$total+=$i['price']*$i['quantity'];}if(!$items)throw new Exception('Your cart is empty.');$st=mysqli_prepare($conn,"INSERT INTO orders(user_id,total_amount,status,payment_method,shipping_address) VALUES(?,?, 'Pending',?,?)");mysqli_stmt_bind_param($st,'idss',$uid,$total,$payment,$address);mysqli_stmt_execute($st);$orderId=mysqli_insert_id($conn);foreach($items as $i){$st=mysqli_prepare($conn,"INSERT INTO order_items(order_id,product_id,quantity,price) VALUES(?,?,?,?)");mysqli_stmt_bind_param($st,'iiid',$orderId,$i['product_id'],$i['quantity'],$i['price']);mysqli_stmt_execute($st);$newStock=$i['stock']-$i['quantity'];$st=mysqli_prepare($conn,"UPDATE products SET stock=? WHERE id=?");mysqli_stmt_bind_param($st,'ii',$newStock,$i['product_id']);mysqli_stmt_execute($st);if($newStock<=5){$msg='Low stock: '.$i['name'].' has only '.$newStock.' left.';$st=mysqli_prepare($conn,"INSERT INTO admin_alerts(message) VALUES(?)");mysqli_stmt_bind_param($st,'s',$msg);mysqli_stmt_execute($st);}}$st=mysqli_prepare($conn,"DELETE FROM cart WHERE user_id=?");mysqli_stmt_bind_param($st,'i',$uid);mysqli_stmt_execute($st);$conn->commit();}catch(Throwable $e){$conn->rollback();die('Order could not be placed: '.htmlspecialchars($e->getMessage()));} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order Complete | ClassyCubic</title><link rel="stylesheet" href="css/style.css"></head><body><?php include __DIR__.'/includes/navbar.php'; ?><div class="form-card"><h2>🎉 Order Placed Successfully</h2><p>Your order number is <b>#<?php echo (int)$orderId; ?></b>.</p><p>Payment: <?php echo htmlspecialchars($payment); ?></p><a class="btn-primary" href="tracking.php">Track Order</a> <a class="btn-secondary" href="shop.php">Continue Shopping</a></div><footer><p>© 2026 ClassyCubic</p></footer></body></html>